    reg clk;
    reg d;
    wire q;

    TopModule uut (
        .clk(clk),
        .d(d),
        .q(q)
    );

    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    initial begin
        d = 0;
        @(posedge clk);
        #1;
        if (q !== 0) begin
            $display("SELFFAIL: expected q=0, got %b", q);
            $finish;
        end

        d = 1;
        @(posedge clk);
        #1;
        if (q !== 1) begin
            $display("SELFFAIL: expected q=1, got %b", q);
            $finish;
        end

        d = 0;
        @(posedge clk);
        #1;
        if (q !== 0) begin
            $display("SELFFAIL: expected q=0, got %b", q);
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule
